def populate_custom_statement_check_results(apps, schema_editor):
    StatementCheckResult = apps.get_model("audits", "StatementCheckResult")
    CustomStatementCheckResult = apps.get_model("audits", "CustomStatementCheckResult")
    known_issues = {}
    for statement_check_result in StatementCheckResult.objects.filter(
        statement_check=None
    ).order_by("id"):
        if statement_check_result.issue_identifier in known_issues:
            custom_statement_check_result = known_issues[
                statement_check_result.issue_identifier
            ]
            if statement_check_result.updated:
                custom_statement_check_result.updated = statement_check_result.updated
            if statement_check_result.retest_state in ("yes", "no"):
                custom_statement_check_result.retest_state = (
                    statement_check_result.retest_state
                )
            for field_name in [
                "public_comment",
                "retest_comment",
                "auditor_information",
            ]:
                statement_check_result_value = getattr(
                    statement_check_result, field_name
                )
                if statement_check_result_value:
                    custom_statement_check_result_value = getattr(
                        custom_statement_check_result, field_name
                    )
                    if (
                        statement_check_result_value
                        == custom_statement_check_result_value
                    ):
                        pass
                    elif custom_statement_check_result_value:
                        setattr(
                            custom_statement_check_result,
                            field_name,
                            f"{custom_statement_check_result_value}\n\nRetest #{statement_check_result.statement_audit.round_number}:\n{statement_check_result_value}",
                        )
                    else:
                        setattr(
                            custom_statement_check_result,
                            field_name,
                            statement_check_result_value,
                        )
            custom_statement_check_result.save()
        else:
            custom_statement_check_result = CustomStatementCheckResult.objects.create(
                simplified_case=statement_check_result.statement_audit.simplified_case,
                statement_audit=statement_check_result.statement_audit,
                id_within_case=statement_check_result.id_within_case,
                issue_identifier=statement_check_result.issue_identifier,
                retest_state=statement_check_result.retest_state,
                auditor_information=statement_check_result.auditor_information,
                public_comment=statement_check_result.public_comment,
                retest_comment=statement_check_result.retest_comment,
                is_deleted=statement_check_result.is_deleted,
                updated=statement_check_result.updated,
            )
        known_issues[statement_check_result.issue_identifier] = (
            custom_statement_check_result
        )
